    { id: 19, stage: 'applications', prompt: with_(say('Kostaldeko A eta B puntuetatik, 500 m-ra daudenak, uhartetxo bat ikusten da, 70° angeluarekin A-n eta 65° angeluarekin B-n. Zer distantziara dago A-tik?', 'Desde dos puntos de la costa, A y B, a 500 m uno de otro, se ve un islote con ángulos de 70° en A y 65° en B. ¿A qué distancia está de A?', 'من نقطتين على الساحل A وB، والمسافة بينهما 500 م، تُرى جزيرة صغيرة بزاوية 70° عند A و65° عند B. كم تبعد عن A؟', 'From two points on the coast, A and B, 500 m apart, an islet is seen at angles of 70° at A and 65° at B. How far is it from A?'), HUNDREDTHS), expected: v('640,86'), hint: say('Uhartetxoko angelua 180° − 70° − 65° da.', 'El ángulo en el islote es 180° − 70° − 65°.', 'الزاوية عند الجزيرة 180° − 70° − 65°.', 'The angle at the islet is 180° − 70° − 65°.'), explanation: same('$\\frac{500\\cdot\\sen 65°}{\\sen 45°}\\approx 640{,}86$') },
    { id: 20, stage: 'applications', prompt: with_(say('50 N eta 80 N-eko bi indarrek 40° osatzen dute. Kalkulatu erresultantea.', 'Dos fuerzas de 50 N y 80 N forman 40°. Halla la resultante.', 'قوتان 50 N و80 N بينهما 40°. أوجد المحصلة.', 'Two forces of 50 N and 80 N make 40°. Find the resultant.'), HUNDREDTHS), expected: v('122,59'), hint: say('Diagonal luzea: kosinuak batu egiten du.', 'La diagonal larga: el coseno suma.', 'القطر الطويل: جيب التمام يضيف.', 'The long diagonal: the cosine adds.'), explanation: same('$\\begin{gathered}R^2=2500+6400+8000\\cdot\\cos 40°\\\\ \\to\\ R\\approx 122{,}59\\end{gathered}$') }
