    { id: 106, stage: 'right', points: 30, context: 'master', prompt: with_(say('ABC triangeluan $c=10$ cm, $A=30°$ eta $B=120°$ dira. Kalkulatu C erpinetik ateratako altuera.', 'En el triángulo ABC, $c=10$ cm, $A=30°$ y $B=120°$. Halla la altura desde C.', 'في المثلث ABC: $c=10$ سم و$A=30°$ و$B=120°$. أوجد الارتفاع النازل من C.', 'In triangle ABC, $c=10$ cm, $A=30°$ and $B=120°$. Find the height from C.'), HUNDREDTHS), expected: v('8,66'), hint: say('Altuera kanpoan erortzen da, B-tik haratago: zatiak kendu egiten dira.', 'La altura cae fuera, más allá de B: los trozos se restan.', 'يقع الارتفاع خارج المثلث بعد B: يُطرح الجزآن.', 'The height falls outside, beyond B: the pieces are subtracted.'), explanation: same('$\\begin{gathered}\\frac{h}{\\tg 30°}-\\frac{h}{\\tg 60°}=10\\\\ \\to\\ h\\approx 8{,}66\\end{gathered}$') },
    { id: 107, stage: 'sines', points: 10, context: 'starter', prompt: with_(say('ABC triangeluan $a=6$, $b=4$ eta $A=50°$ dira. Kalkulatu B.', 'En el triángulo ABC, $a=6$, $b=4$ y $A=50°$. Halla B.', 'في المثلث ABC: $a=6$ و$b=4$ و$A=50°$. أوجد B.', 'In triangle ABC, $a=6$, $b=4$ and $A=50°$. Find B.'), TENTHS), expected: v('30,7'), hint: say('$b<a$ denez, B zorrotza da: soluzio bakarra dago.', 'Como $b<a$, B es agudo: solo hay una solución.', 'بما أن $b<a$ فالزاوية B حادة: يوجد حل واحد.', 'Since $b<a$, B is acute: there is only one solution.'), explanation: same('$\\begin{gathered}\\sen B=\\frac{4\\cdot\\sen 50°}{6}\\approx 0{,}511\\\\ \\to\\ B\\approx 30{,}7°\\end{gathered}$') },
    { id: 108, stage: 'sines', points: 20, context: 'advanced', prompt: with_(say('ABC triangeluan $a=7$, $b=10$ eta $A=40°$ dira. Bi triangelu daude: eman $c$ aldearen baliorik handiena.', 'En el triángulo ABC, $a=7$, $b=10$ y $A=40°$. Hay dos triángulos: da el mayor valor posible de $c$.', 'في المثلث ABC: $a=7$ و$b=10$ و$A=40°$. يوجد مثلثان: أعطِ أكبر قيمة ممكنة لـ $c$.', 'In triangle ABC, $a=7$, $b=10$ and $A=40°$. There are two triangles: give the largest possible value of $c$.'), HUNDREDTHS), expected: v('10,43'), hint: say('B zorrotzak C handiagoa ematen du, eta C handiagoak $c$ handiagoa.', 'B agudo da C mayor, y C mayor da $c$ mayor.', 'B الحادة تعطي C أكبر، وC الأكبر تعطي $c$ أكبر.', 'An acute B gives a larger C, and a larger C gives a larger $c$.'), explanation: same('$\\begin{gathered}B\\approx 66{,}7°\\\\ \\to\\ C\\approx 73{,}3°\\\\ \\to\\ c=\\frac{7\\cdot\\sen 73{,}3°}{\\sen 40°}\\approx 10{,}43\\end{gathered}$') },
    { id: 109, stage: 'sines', points: 30, context: 'master', prompt: say('$b=10$ eta $A=30°$ izanik, $a$ aldearen zer baliok ematen du triangelu bakarra, angeluzuzena?', 'Con $b=10$ y $A=30°$, ¿qué valor de $a$ da un único triángulo, rectángulo?', 'مع $b=10$ و$A=30°$، أي قيمة لـ $a$ تعطي مثلثًا واحدًا قائمًا؟', 'With $b=10$ and $A=30°$, what value of $a$ gives a single triangle, a right-angled one?'), expected: n(5), hint: say('Konpasak zuzena ukitu besterik ez du egiten: $a$ C-tik zuzenerako distantzia da.', 'El compás justo toca la recta: $a$ es la distancia de C a ella.', 'يلمس الفرجار المستقيم بالكاد: $a$ هو بعد C عنه.', 'The compass just touches the line: $a$ is the distance from C to it.'), explanation: same('$a=10\\cdot\\sen 30°=5$') },
    { id: 110, stage: 'cosines', points: 10, context: 'starter', prompt: say('Triangelu baten aldeak 5, 7 eta 8 cm dira. Kalkulatu 7 cm-ko aldearen aurkako angelua.', 'Los lados de un triángulo miden 5, 7 y 8 cm. Halla el ángulo opuesto al lado de 7 cm.', 'أضلاع مثلث 5 و7 و8 سم. أوجد الزاوية المقابلة للضلع 7 سم.', 'The sides of a triangle are 5, 7 and 8 cm. Find the angle opposite the 7 cm side.'), expected: n(60), hint: say('Askatu 7 aldearen parean dagoen angeluaren kosinua.', 'Despeja el coseno del ángulo que está frente al 7.', 'اعزل جيب تمام الزاوية المقابلة للضلع 7.', 'Solve for the cosine of the angle opposite the 7.'), explanation: same('$\\begin{gathered}\\cos B=\\frac{25+64-49}{80}=\\frac{1}{2}\\\\ \\to\\ B=60°\\end{gathered}$') },
    { id: 111, stage: 'cosines', points: 20, context: 'advanced', prompt: with_(say('ABC triangeluan $a=12$ cm, $c=9$ cm eta $B=70°$ dira. Kalkulatu C.', 'En el triángulo ABC, $a=12$ cm, $c=9$ cm y $B=70°$. Halla C.', 'في المثلث ABC: $a=12$ سم و$c=9$ سم و$B=70°$. أوجد C.', 'In triangle ABC, $a=12$ cm, $c=9$ cm and $B=70°$. Find C.'), TENTHS), expected: v('43,5'), hint: say('Lehenik $b$ aldea kosinuarekin; C alde txikienaren angelua da.', 'Primero el lado $b$ con el coseno; C es el ángulo del lado menor.', 'أولًا الضلع $b$ بجيب التمام، وC زاوية أصغر ضلع.', 'First the side $b$ with the cosine; C is the angle of the shortest side.'), explanation: same('$\\begin{gathered}b^2=144+81-216\\cdot\\cos 70°\\\\ \\to\\ b\\approx 12{,}29\\\\ \\sen C=\\frac{9\\cdot\\sen 70°}{12{,}29}\\\\ \\to\\ C\\approx 43{,}5°\\end{gathered}$') },
    { id: 112, stage: 'cosines', points: 30, context: 'master', prompt: say('Triangelu baten aldeak 7, 8 eta 13 cm dira. Kalkulatu haren angelu handiena.', 'Los lados de un triángulo miden 7, 8 y 13 cm. Halla su ángulo mayor.', 'أضلاع مثلث 7 و8 و13 سم. أوجد أكبر زواياه.', 'The sides of a triangle are 7, 8 and 13 cm. Find its largest angle.'), expected: n(120), hint: say('13 cm-ko aldearen parean.', 'Frente al lado de 13 cm.', 'مقابل الضلع 13 سم.', 'Opposite the 13 cm side.'), explanation: same('$\\begin{gathered}\\cos C=\\frac{49+64-169}{112}=-\\frac{1}{2}\\\\ \\to\\ C=120°\\end{gathered}$') },
    { id: 113, stage: 'applications', points: 10, context: 'starter', prompt: say('Heronen formularekin, kalkulatu aldeak 5, 12 eta 13 m dituen triangeluaren azalera.', 'Halla con la fórmula de Herón el área del triángulo de lados 5, 12 y 13 m.', 'أوجد بصيغة هيرون مساحة المثلث الذي أضلاعه 5 و12 و13 م.', 'Use Heron\'s formula to find the area of the triangle with sides 5, 12 and 13 m.'), expected: n(30), hint: say('Perimetro-erdia 30 zenbakiaren erdia da.', 'El semiperímetro es la mitad de 30.', 'نصف المحيط نصف 30.', 'The semi-perimeter is half of 30.'), explanation: same('$\\begin{gathered}s=15\\\\  S=\\sqrt{15\\cdot 10\\cdot 3\\cdot 2}=30\\end{gathered}$') },
    { id: 114, stage: 'applications', points: 20, context: 'advanced', prompt: with_(say('Paralelogramo baten aldeak 6 cm eta 10 cm dira, eta 60° osatzen dute. Kalkulatu haren azalera.', 'Un paralelogramo tiene lados de 6 cm y 10 cm que forman 60°. Halla su área.', 'متوازي أضلاع ضلعاه 6 سم و10 سم وبينهما 60°. أوجد مساحته.', 'A parallelogram has sides of 6 cm and 10 cm that make 60°. Find its area.'), HUNDREDTHS), expected: v('51,96'), hint: say('Bi triangelu berdin dira.', 'Son dos triángulos iguales.', 'إنه مثلثان متطابقان.', 'It is two equal triangles.'), explanation: same('$S=6\\cdot 10\\cdot\\sen 60°\\approx 51{,}96$') },
    { id: 115, stage: 'applications', points: 30, context: 'master', prompt: with_(say('Bi itsasontzi portu batetik irteten dira, 50° osatzen duten norabideetan, 12 km/h eta 18 km/h abiaduran. Zer distantzia dago haien artean 2 orduren buruan?', 'Dos barcos salen de un puerto con rumbos que forman 50°, a 12 km/h y a 18 km/h. ¿Qué distancia los separa a las 2 horas?', 'تخرج سفينتان من ميناء في اتجاهين بينهما 50°، بسرعة 12 كم/س و18 كم/س. كم تبعد إحداهما عن الأخرى بعد ساعتين؟', 'Two ships leave a port on courses that make 50°, at 12 km/h and 18 km/h. How far apart are they after 2 hours?'), HUNDREDTHS), expected: v('27,59'), hint: say('2 orduren buruan, portutik 24 km-ra eta 36 km-ra daude.', 'A las 2 horas están a 24 km y a 36 km del puerto.', 'بعد ساعتين تكونان على بعد 24 كم و36 كم من الميناء.', 'After 2 hours they are 24 km and 36 km from the port.'), explanation: same('$\\begin{gathered}d^2=24^2+36^2-2\\cdot 24\\cdot 36\\cdot\\cos 50°\\\\ \\to\\ d\\approx 27{,}59\\end{gathered}$') }
